package com.reevil.client.urias;

import com.reevil.ReEvilMod;
import com.reevil.client.mrx.MrXModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.resources.ResourceLocation;

/** Own silhouette (generated by tools/variantgen.py): the MrXModel rig, so all clips apply, with replaced/added parts. */
public class UriasModel extends MrXModel {
    public static final ModelLayerLocation LAYER = new ModelLayerLocation(new ResourceLocation(ReEvilMod.MODID, "urias"), "main");
    public UriasModel(ModelPart root) { super(root); }
    public static LayerDefinition createBodyLayer() {
        MeshDefinition mesh = MrXModel.mesh();
        PartDefinition root = mesh.getRoot();
        root.getChild("base").getChild("torso").addOrReplaceChild("muscle", CubeListBuilder.create()
            .texOffs(0, 64).addBox(-5.5f, -10.5f, -3, 11, 7, 6)
            .texOffs(34, 64).addBox(-8, -12, -3.5f, 4, 4, 7)
            .texOffs(56, 64).addBox(4, -12, -3.5f, 4, 4, 7),
            PartPose.ZERO);
        root.getChild("base").getChild("torso").addOrReplaceChild("ridge", CubeListBuilder.create()
            .texOffs(78, 64).addBox(-1, -11, 2.5f, 2, 6, 3)
            .texOffs(88, 64).addBox(-4, -9, 2.5f, 2, 5, 3)
            .texOffs(98, 64).addBox(2, -9, 2.5f, 2, 5, 3)
            .texOffs(108, 64).addBox(-1, -3, 2.5f, 2, 4, 3),
            PartPose.ZERO);
        root.getChild("base").getChild("torso").getChild("neck").getChild("head").addOrReplaceChild("crest", CubeListBuilder.create()
            .texOffs(0, 77).addBox(-1, -10, -3, 2, 4, 6)
            .texOffs(16, 77).addBox(-4, -4, -4.4f, 8, 2, 1),
            PartPose.ZERO);
        return LayerDefinition.create(mesh, 128, 88);
    }
}
